-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Elder abuse — types, red flags, mandatory reporting - Part 2 (101-200)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-abuse' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-abuse not found.';
    END IF;

END $$;
COMMIT;
