    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 96-year-old female named Esther is brought to the clinic with bruising. Which of the following bruising patterns is most highly specific for intentional physical abuse rather than accidental trauma from typical geriatric falls?', '["A linear bruise along the elbow crease after a minor slip on ice", "A small ecchymosis over the dorsal aspect of the hand from an accidental bump", "Symmetrical bruises on the bilateral patellae (knees) following a trip-and-fall accident", "Multiple large bruises on the neck, ears, lateral face, upper arms, and trunk in various stages of healing", "A single bruise on the anterior tibia (shin) resulting from bumping into a coffee table"]'::jsonb, 3, 'Accidental bruises in older adults typically occur on **bony prominences** such as the anterior shins, knees, elbows, and forehead, and are usually single or localized. In contrast, **intentional physical abuse** is strongly suggested by bruises located on **soft, protected areas** (such as the neck, ears, inner arms, lateral face, chest, abdomen, back, and buttocks) and bruises in **various stages of healing** (indicating repeated, chronic trauma). Bruises larger than 5 cm on the arms or trunk should also raise suspicion. (Ref: Hazzard''s Ch. 14; Lachs & Pillemer, N Engl J Med 2015; UWorld Step 2 CK)'),
